VALUES
  ('faq', 'FAQ', '{"en":"Support","de":"Support","fr":"Assistance","es":"Ayuda"}'::jsonb, '{"en":"Frequently Asked","de":"Häufig gestellte","fr":"Questions","es":"Preguntas"}'::jsonb, '{"en":"Questions","de":"Fragen","fr":"fréquentes","es":"frecuentes"}'::jsonb, '{"en":"Clear answers to common questions about our process, pricing, technology, and ongoing support.","de":"Klare Antworten auf häufige Fragen zu unserer Arbeitsweise, unseren Preisen, Technologien und Supportleistungen.","fr":"Des réponses claires aux questions fréquentes concernant notre méthode, nos tarifs, nos technologies et notre accompagnement.","es":"Respuestas claras a preguntas frecuentes sobre nuestro proceso, precios, tecnología y soporte continuo."}'::jsonb, true, 80)
